1	package claude
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"regexp"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// sessionIDPattern matches a Claude session UUID. checkpoint_id comes from
14	// cmux's surface metadata and is interpolated into a filesystem glob, so it is
15	// validated to this shape first — otherwise `../` or glob metacharacters
16	// (`*`, `?`, `[`) could escape ~/.claude/projects or match unintended files.
17	var sessionIDPattern = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)
18	
19	// maxTranscriptFileBytes bounds how much of a transcript file is read into
20	// memory. Claude session files grow forward, so for a larger file only the
21	// tail (most recent conversation) is read.
22	const maxTranscriptFileBytes = 32 * 1024 * 1024
23	
24	// cacheEntry holds an already-rendered transcript with its file identity.
25	type cacheEntry struct {
26		modTime time.Time
27		size    int64
28		text    string
29	}
30	
31	// Resolver locates and renders Claude session transcripts.
32	type Resolver struct {
33		home  string
34		cache sync.Map // keyed by absolute path → *cacheEntry
35	}
36	
37	// NewResolver creates a Resolver that resolves $HOME via os.UserHomeDir.
38	func NewResolver() *Resolver {
39		home, _ := os.UserHomeDir()
40		return &Resolver{home: home}
41	}
42	
43	// Render returns the rendered transcript for a surface's resume_binding.
44	//
45	// supported reports whether the binding describes a Claude surface at all.
46	// If supported is true but text is empty (""), no transcript file was found yet.
47	// sessionID is the base filename (without .jsonl) of the active transcript.
48	func (r *Resolver) Render(resumeBinding map[string]any, maxMessages int) (text string, supported bool, sessionID string, err error) {
49		if resumeBinding == nil {
50			return "", false, "", nil
51		}
52		kind, _ := resumeBinding["kind"].(string)
53		if kind != "claude" {
54			return "", false, "", nil
55		}
56	
57		transcriptPath, err := r.resolveTranscriptPath(resumeBinding)
58		if err != nil {
59			return "", true, "", err
60		}
61		if transcriptPath == "" {
62			// Claude surface but no transcript file found yet.
63			return "", true, "", nil
64		}
65	
66		sessionID = strings.TrimSuffix(filepath.Base(transcriptPath), ".jsonl")
67	
68		info, err := os.Stat(transcriptPath)
69		if err != nil {
70			return "", true, sessionID, err
71		}
72	
73		// Check cache.
74		if v, ok := r.cache.Load(transcriptPath); ok {
75			entry := v.(*cacheEntry)
76			if entry.modTime.Equal(info.ModTime()) && entry.size == info.Size() {
77				return entry.text, true, sessionID, nil
78			}
79		}
80	
81		data, err := readTail(transcriptPath, info.Size(), maxTranscriptFileBytes)
82		if err != nil {
83			return "", true, sessionID, err
84		}
85	
86		rendered := renderJSONL(data, maxMessages)
87		r.cache.Store(transcriptPath, &cacheEntry{
88			modTime: info.ModTime(),
89			size:    info.Size(),
90			text:    rendered,
91		})
92		return rendered, true, sessionID, nil
93	}
94	
95	// resolveTranscriptPath returns the transcript .jsonl file for the surface's
96	// resume_binding, or "" if none is found.
97	//
98	// checkpoint_id names the surface's SPECIFIC session and is the authoritative
99	// mapping — many surfaces share one cwd (e.g. cmux worktrees), so "newest file
100	// in the project dir" would collapse them all onto the same transcript. cmux's
101	// agent hook keeps checkpoint_id pointed at each surface's live session, so the
102	// <checkpoint_id>.jsonl file is used directly. The cwd encoding is only a
103	// best-effort fallback when no checkpoint_id is present.
104	func (r *Resolver) resolveTranscriptPath(rb map[string]any) (string, error) {
105		projectsDir := filepath.Join(r.home, ".claude", "projects")
106	
107		// Strategy 1: the checkpoint_id names the surface's exact session file.
108		// Only accept a well-formed session UUID — it's interpolated into a glob,
109		// so `../` or `*?[` in a malformed value must never reach the filesystem.
110		if checkpointID, _ := rb["checkpoint_id"].(string); sessionIDPattern.MatchString(checkpointID) {
111			pattern := filepath.Join(projectsDir, "*", checkpointID+".jsonl")
112			matches, err := filepath.Glob(pattern)
113			if err != nil {
114				return "", err
115			}
116			// Defense in depth: the match must resolve inside projectsDir.
117			if len(matches) > 0 && isWithin(projectsDir, matches[0]) {
118				return matches[0], nil
119			}
120		}
121	
122		// Strategy 2 (fallback): no checkpoint_id — encode the cwd and take the
123		// most-recently-modified session in that project dir.
124		if cwd, _ := rb["cwd"].(string); cwd != "" {
125			dir := filepath.Join(projectsDir, encodeCWD(cwd))
126			if _, err := os.Stat(dir); err == nil {
127				return latestJSONL(dir)
128			}
129		}
130	
131		return "", nil
132	}
133	
134	// readTail reads at most maxBytes from the end of the file at path. Claude
135	// session files grow forward, so the tail is the most recent conversation and
136	// this bounds memory for very large sessions. A partial first line (from
137	// cutting mid-line) is harmless — renderJSONL skips unparseable lines.
138	func readTail(path string, size, maxBytes int64) ([]byte, error) {
139		if size <= maxBytes {
140			return os.ReadFile(path)
141		}
142		f, err := os.Open(path)
143		if err != nil {
144			return nil, err
145		}
146		defer f.Close()
147		buf := make([]byte, maxBytes)
148		n, err := f.ReadAt(buf, size-maxBytes)
149		if err != nil && n == 0 {
150			return nil, err
151		}
152		return buf[:n], nil
153	}
154	
155	// isWithin reports whether path is inside dir (or equal to it).
156	func isWithin(dir, path string) bool {
157		rel, err := filepath.Rel(dir, filepath.Clean(path))
158		if err != nil {
159			return false
160		}
161		return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
162	}
163	
164	// encodeCWD converts an absolute cwd path to the Claude project directory name.
165	// e.g. "/Users/marlin/wrinkles" → "-Users-marlin-wrinkles"
166	func encodeCWD(cwd string) string {
167		stripped := strings.TrimPrefix(cwd, "/")
168		replacer := strings.NewReplacer("/", "-", ".", "-", "_", "-")
169		return "-" + replacer.Replace(stripped)
170	}
171	
172	// latestJSONL returns the most-recently-modified *.jsonl file in dir, or "".
173	func latestJSONL(dir string) (string, error) {
174		entries, err := os.ReadDir(dir)
175		if err != nil {
176			return "", err
177		}
178	
179		var bestPath string
180		var bestMod time.Time
181	
182		for _, e := range entries {
183			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
184				continue
