package claude

import (
	"fmt"
	"testing"
)

// Temporary, non-hermetic: runs the resolver against the real ~/.claude for the
// surfaces reported as showing the wrong history. Deleted after verification.
func TestLiveCheck(t *testing.T) {
	cases := []struct {
		name string
		cp   string
	}{
		{"broken: PEPO signal method", "cbd25a24-f36b-4c2a-b98f-f141ab449621"},
		{"broken: video eval framework", "ea89bc76-0786-48bf-8821-afeaad8d2266"},
		{"broken: GitHub login mini", "3c4d33d7-3c17-4f09-817f-932e17f4f9e7"},
		{"working: AMI HTML page", "ec183c22-1035-40b1-bccd-68f25233ada6"},
		{"working: screenshot app", "499cfccc-3461-4e64-9caa-8ee106f40efc"},
	}
	r := NewResolver()
	for _, c := range cases {
		res, err := r.Render(map[string]any{
			"kind":          "claude",
			"checkpoint_id": c.cp,
			"cwd":           "/Users/marlin/wrinkles",
		}, 300)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		head := res.Text
		if len(head) > 60 {
			head = head[:60]
		}
		fmt.Printf("%-32s missing=%-5v session=%s chars=%d head=%q\n",
			c.name, res.SessionMissing, res.SessionID[:8], len(res.Text), head)
	}
}

